
/* ================= КАБИНЕТ ПАРТНЁРА (вход по QR-ссылке ?p=НОМЕР) ================= */
// (переменная _partnerQR объявлена в начале скрипта)
// единое окно партнёра в базу — через Edge Function partner-cabinet
async function callPartnerCabinet(action,payload){
  try{
    const res=await fetch(`${SUPABASE_URL}/functions/v1/partner-cabinet`,{
      method:'POST',
      headers:{'Content-Type':'application/json','apikey':SUPABASE_ANON,'Authorization':'Bearer '+SUPABASE_ANON},
      body:JSON.stringify(Object.assign({action,qr_code:_partnerQR},payload||{})),
    });
    const out=await res.json().catch(()=>({}));
    if(!res.ok)return {error:out.error||('Ошибка '+res.status)};
    return out;
  }catch(e){return {error:String(e&&e.message||e)};}
}
async function openPartnerCabinet(code){
  hideSplash();
  _partnerQR=String(code||'').trim();
  const r=await callPartnerCabinet('init');
  if(r.error||!r.partner){
    document.body.innerHTML=`<div class="pcab-err">Кабинет не найден.<br><small>Проверьте ссылку или QR-код.</small></div>`;
    return;
  }
  // справочники из ответа функции
  const d=r.dirs||{};
  S.delivery=d.delivery_types||[];S.statuses=d.statuses||[];S.orderStatuses=d.order_statuses||[];
  S.courier_cities=d.courier_cities||[];S.cities=d.cities||[];
  renderPartnerCabinet(r.partner);
}

async function loadPartnerDirs(){
  // справочники уже загружены в openPartnerCabinet через init; оставлено для совместимости
  return (S.delivery||[]).length>0;
}

