// отрисовка активной вкладки кабинета партнёра
function renderPartnerTab(partner){
  const v=$('pcabView');if(!v)return;
  const tab=partner.__tab||'home';
  if(tab==='home')return renderPTabHome(partner);
  if(tab==='orders')return renderPTabOrders(partner);
  if(tab==='pickups')return renderPTabPickups(partner);
  if(tab==='profile')return renderPTabProfile(partner);
}

// ── Вкладка ГЛАВНАЯ ──
function renderPTabHome(partner){
  const v=$('pcabView');
  const hour=new Date().getHours();
  const greet=hour<6?'Доброй ночи':hour<12?'Доброе утро':hour<18?'Добрый день':'Добрый вечер';
  const firstName=(partner.name||'').split(' ')[0]||partner.name||'';
  v.innerHTML=`
    <div class="pcab-top">
      <div class="pcab-brand">
        <img class="pcab-logo-img" src="data:image/png;base64," alt="Jyldam Logistics">
        <div><div class="pcab-store">${esc(partner.name)}</div><div class="pcab-sub">Кабинет партнёра · Jyldam Logistics</div></div>
      </div>
    </div>
    <div class="pcab-hello"><div class="ph-greet">${esc(greet)}, ${esc(firstName)} 👋</div><div class="ph-sub" id="phStats">Загрузка…</div></div>
    <button class="pcab-call" id="pcabCall">📦 Вызвать курьера</button>
    <div class="pcab-info">
      <div class="pcab-row"><span>📍 Адрес</span><b>${esc(partner.address||'—')}</b></div>
      <div class="pcab-row"><span>📞 Телефон</span><b>${partner.phone?esc(phoneDisplay(partner.phone)):'—'}</b></div>
    </div>`;
  $('pcabCall').onclick=()=>partnerCallCourier(partner);
  loadPartnerHomeStats(partner);
}
async function loadPartnerHomeStats(partner){
  const el=$('phStats');if(!el)return;
  try{
    const r=await callPartnerCabinet('home_stats');
    const n=r&&!r.error?(r.today_count||0):0;
    el.textContent=`Сегодня отправлений: ${n}`;
  }catch(e){el.textContent='';}
}

