// загрузка и отрисовка заказов партнёра с фильтром по дате создания и дате забора
async function loadPartnerOrders(partner){
  const box=$('pcabList');if(!box)return;
  let rows=[];
  try{
    const r=await callPartnerCabinet('orders');
    rows=(r&&!r.error)?(r.orders||[]):[];
  }catch(e){console.error(e);}
  partner.__orders=rows;
  drawPartnerOrders(partner);
}
function drawPartnerOrders(partner){
  const box=$('pcabList');if(!box)return;
  const pf=partner.__pf||{from:'',to:''};
  const q=(($('pcabq')&&$('pcabq').value)||'').toLowerCase().trim();
  let rows=(partner.__orders||[]).filter(o=>{
    const cd=(o.created_at||'').slice(0,10);
    const pd=(o.pickup_date||'').slice(0,10);
    // фильтр по дате: показываем, если ХОТЬ ОДНА из дат (создания или забора) попадает в диапазон
    if(pf.from){ if(!((cd&&cd>=pf.from)||(pd&&pd>=pf.from)))return false; }
    if(pf.to){ if(!((cd&&cd<=pf.to)||(pd&&pd<=pf.to)))return false; }
    if(q){
      const hay=[o.code,o.client,o.track,o.address,o.city_text,phoneDisplay(o.phone)].join(' ').toLowerCase();
      if(!hay.includes(q))return false;
    }
    return true;
  });
  if(!rows.length){box.innerHTML='<div class="pcab-empty">Заказов нет</div>';return;}
  box.innerHTML=rows.map(o=>{
    const collected=partnerOrderCollected(o);
    const dtype=o.delivery_id?deliveryName(o.delivery_id):'не выбран';
    const st=o.status_id?(orderStatusObj(o.status_id)||{}).name:'';
    return `<div class="pcab-ord ${collected?'locked':''}" data-ord="${o.id}">
      <div class="pcab-ord-h">
        <b>#${esc(o.code)}</b>
        <span class="pcab-ord-date">${esc(fmtDate(o.created_at))}</span>
      </div>
      <div class="pcab-ord-sub">${esc(o.client||'без клиента')}${o.phone?(' · '+esc(phoneDisplay(o.phone))):''}</div>
      <div class="pcab-ord-meta">
        <span class="pcab-tag">${esc(dtype)}</span>
        ${o.track?`<span class="pcab-tag">трек: ${esc(o.track)}</span>`:''}
        ${st?`<span class="pcab-tag">${esc(st)}</span>`:''}
        ${collected?'<span class="pcab-tag lock">🔒 забран</span>':''}
      </div>
    </div>`;
  }).join('');
  // двойной тап / одиночный тап — открыть заказ
  box.querySelectorAll('[data-ord]').forEach(card=>{
    const open=()=>partnerEditOrder(partner,card.dataset.ord);
    card.ondblclick=open;
    let lastTap=0;
    card.onclick=()=>{const now=Date.now();if(now-lastTap<400){open();}lastTap=now;};
  });
}

// считаем заказ «забранным» (нельзя редактировать), если его статус или статус заявки завершающий
function partnerOrderCollected(o){
  if(o.status_id&&isCollectedOrderStatus(o.status_id))return true;
  return false;
}
function isCollectedOrderStatus(id){const s=orderStatusObj(id);if(!s)return false;return /забра|забро|собра|вруч|доставлен|выдан/i.test(s.name||'');}

// вызвать курьера: спросить количество, создать ОДНУ заявку + N заказов, открыть заполнение
async function partnerCallCourier(partner){
  const n=prompt('Сколько заказов нужно забрать?','1');
  if(n===null)return;
  const cnt=Math.max(1,parseInt(n,10)||1);
  const btn=$('pcabCall');if(btn){btn.disabled=true;btn.textContent='Создаём…';}
  try{
    // до 12:00 — заявка на сегодня, после 12:00 — на завтра (курьер уже не успеет сегодня)
    const nowLocal=new Date();
    const afterNoon=nowLocal.getHours()>=12;
    if(afterNoon)nowLocal.setDate(nowLocal.getDate()+1);
    const tzOff=nowLocal.getTimezoneOffset();
    const today=new Date(nowLocal.getTime()-tzOff*60000).toISOString().slice(0,10);
    // эта заявка всегда курьерская (кнопка «Вызвать курьера» в кабинете) — если у партнёра именно
    // курьерский тариф стоит ровно 0, он оплачивает эту доставку сам отдельно, не через сумму
    // заказа. Почтовый тариф тут ни при чём — заявка не почтовая.
    const zeroTariffs=isExplicitZero(partner.tariff_courier);
    // строим заготовки заказов на клиенте (без pickup_id — его проставит функция)
    const orderRows=[];
    for(let i=0;i<cnt;i++){
      orderRows.push({
        code:String(Math.floor(1000000+Math.random()*9000000)),
        sender:partner.name,pickup_date:today,
        delivery_id:defaultCourierDeliveryId(),
        pickup_city_id:partner.city_id||null,
        sales_id:partner.sales_id||null,processor_id:partner.processor_id||null,
        order_sum:zeroTariffs?0:(partner.tariff_courier||null),cost:zeroTariffs?0:(partner.tariff_courier||0),
        paid_by_sender:zeroTariffs,
        order_sum_orig:(zeroTariffs&&partner.direct_pay_amount!=null)?partner.direct_pay_amount:null,
        created_at:new Date().toISOString(),
      });
    }
    // доп. поля заявки (если новую придётся создать)
    const pickup_extra={
      district_id:partner.district_id||null,
      sales_id:partner.sales_id||null,processor_id:partner.processor_id||null,
      created_at:new Date().toISOString(),
    };
    const r=await callPartnerCabinet('call_courier',{orders:orderRows,pickup_extra,pickup_date:today});
    if(r.error)throw new Error(r.error);
    if(btn){btn.disabled=false;btn.textContent='📦 Вызвать курьера';}
    const tomorrow=(r.courier_tomorrow!=null)?r.courier_tomorrow:afterNoon; // сервер точнее (не зависит от часов браузера)
    alert(tomorrow
      ? '✅ Заявка создана!\n\nСейчас после 12:00 — курьер заберёт посылки ЗАВТРА.'
      : '✅ Заявка создана!\n\nСейчас до 12:00 — курьер заберёт посылки СЕГОДНЯ.');
    partnerFillOrders(partner,r.orders||[]);
  }catch(e){
    if(btn){btn.disabled=false;btn.textContent='📦 Вызвать курьера';}
    alert('Не удалось создать: '+(e&&e.message||e));
  }
}
// (счётчик заявки пересчитывается внутри функции call_courier)
async function syncPickupOrdersCount(pickupId){/* больше не нужно на клиенте */}

// общий HTML полей одного заказа (используется и при создании, и при редактировании)
// первый курьерский / первый почтовый тип из справочника
function defaultCourierDeliveryId(){const d=(S.delivery||[]).find(x=>/курьер/i.test(x.name||''));return d?d.id:null;}
function defaultMailDeliveryId(){const d=(S.delivery||[]).find(x=>!/курьер/i.test(x.name||''));return d?d.id:null;}

function courierCitiesSorted(){return (S.courier_cities||[]).slice().sort((a,b)=>(a.name||'').localeCompare(b.name||'','ru'));}
function partnerOrderFieldsHtml(o,i){
  // почтовый, если у заказа выбран не-курьерский тип доставки
  const isMail=o.delivery_id?!isCourierDelivery(o.delivery_id):false;
  return `<div class="pfill-card" data-ord="${o.id}">
    <div class="pfill-h">${i!=null?('Заказ '+(i+1)+' · '):''}#${esc(o.code)}
      <button type="button" class="pfill-print" data-printlbl="${o.id}">🖨 Этикетка на пакет</button></div>
    <div class="pfill-note">Распечатайте и приклейте на пакет ДО того, как отдадите его курьеру — это единственный способ отличить одинаковые запечатанные пакеты друг от друга.</div>
    <label class="pfill-l">Штрих-код (если на пакете уже есть свой — отсканируйте)</label>
    <div class="pfill-track">
      <input id="trk_${o.id}" value="${esc(o.track||'')}" placeholder="Необязательно, если клеите нашу этикетку">
      <button type="button" class="pfill-scan" data-scan="${o.id}">📷 Скан</button>
    </div>
    <label class="pfill-l">Тип доставки</label>
    <div class="pfill-delivery">
      <label class="pfill-check"><input type="checkbox" id="cour_chk_${o.id}" data-courchk="${o.id}" ${!isMail?'checked':''}> 🚚 Курьерская доставка</label>
      <label class="pfill-check"><input type="checkbox" id="mail_${o.id}" data-mailchk="${o.id}" ${isMail?'checked':''}> ✉️ Почтовая доставка</label>
    </div>
    <div class="pfill-cour" id="cour_${o.id}" style="${isMail?'display:none':''}">
      <div class="pfill-cour-h">🚚 Курьерская доставка по городам:</div>
      <div class="pfill-cour-list">${courierCitiesSorted().map(c=>esc(c.name)).join(' · ')||'список городов пуст'}</div>
      <div class="pfill-cour-note">В эти города мы доставляем курьерской службой. Остальные направления — отметьте «Почтовая доставка».</div>
    </div>
    <label class="pfill-l">Комментарий</label>
    <textarea id="cmt_${o.id}" class="pfill-area" placeholder="Укажите: ФИО · Город · Адрес · Номер телефона" rows="5">${esc(o.comment||'')}</textarea>
    <div class="pfill-hint">Можно скопировать данные из переписки (например, WhatsApp) и вставить сюда. Обязательно указать: ФИО получателя, город, адрес, номер телефона.</div>
  </div>`;
}
// две взаимоисключающие галочки: курьерская / почтовая. Источник правды — «Почтовая»
function partnerToggleMail(oid){
  const mail=$('mail_'+oid);const cour=$('cour_chk_'+oid);const box=$('cour_'+oid);
  if(!mail)return;
  if(cour)cour.checked=!mail.checked; // курьерская = противоположность почтовой
  if(box)box.style.display=mail.checked?'none':'';
}
// клик по «Курьерская» — снимает «Почтовая» и наоборот
function partnerToggleCourier(oid){
  const mail=$('mail_'+oid);const cour=$('cour_chk_'+oid);
  if(mail&&cour)mail.checked=!cour.checked;
  partnerToggleMail(oid);
}
// печать этикетки заказа для партнёра — код заказа крупно + штрихкод-полоски, наклеить на пакет ДО отдачи курьеру.
// Это и есть тот самый идентификатор, по которому курьер потом отличит одинаковые запечатанные пакеты друг от друга.
function printPartnerOrderLabel(o,partner){
  if(!o)return;
  const code=String(o.code||'');
  const bars=code.split('').map(d=>{const w=(2.3+(parseInt(d,10)%3)*1.5).toFixed(2);return `<span style="display:inline-block;width:${w}mm;height:100%;background:#000;margin-right:0.4mm"></span>`;}).join('');
  const body=`
    <div class="wh-label" id="whLabelPrint" style="height:44mm">
      <div class="wh-label-name">${esc(partner&&partner.name||'')}</div>
      <div class="wh-label-bars">${bars}</div>
      <div class="wh-label-code" style="font-size:5.5mm">${esc(code)}</div>
      <div class="wh-label-sku">Заказ · наклеить на пакет</div>
    </div>
    <div class="hint" style="text-align:center;margin-top:8px">Размер этикетки: 58×40 мм. Приклейте на пакет ДО передачи курьеру — курьер отличает одинаковые пакеты именно по этому коду.</div>
    <div style="text-align:center;margin-top:10px"><button class="btn primary" onclick="window.print()">🖨 Печать</button></div>`;
  showInfo(`Этикетка заказа #${esc(code)}`,body);
}
// собрать значения полей одного заказа для сохранения
// разбирает свободный текст «ФИО · Город · Адрес · Телефон», который вводит партнёр, на отдельные
// поля — иначе они оставались пустыми в самом заказе (а печатаются на бланках/накладных именно из них,
// не из комментария)
function parsePartnerComment(text){
  text=(text||'').trim();
  if(!text)return{client:'',phone:'',address:''};
  // телефон — ищем похожую на казахстанский номер последовательность цифр
  const phoneMatch=text.match(/(?:\+?7|8)?[\s\-\(]*\d{3}[\s\-\)]*\d{3}[\s\-]*\d{2}[\s\-]*\d{2}/);
  let phone='';
  if(phoneMatch){
    phone=phoneMatch[0].replace(/\D/g,'');
    if(phone.length===11)phone=phone.slice(1); // убираем код страны 7/8, оставляем 10 цифр
  }
  const rest=phoneMatch?text.replace(phoneMatch[0],' '):text;
  // делим на куски по типичным разделителям, которые просим использовать в подсказке (· , ; перенос строки)
  const parts=rest.split(/[·\n,;]+/).map(s=>s.trim()).filter(Boolean);
  // ФИО — первый кусок, где есть буквы и он не похож на «г. .../ул. .../мкр ...»
  let client='';
  const nameIdx=parts.findIndex(p=>/[A-Za-zА-Яа-яЁё]{2,}/.test(p)&&!/^(г\.|город|ул\.|улица|мкр|дом|кв\.|пос\.)/i.test(p));
  if(nameIdx>=0){client=parts[nameIdx];parts.splice(nameIdx,1);}
  const address=parts.join(', ');
  return{client,phone,address};
}
function partnerCollectFields(o){
  const isMail=!!(($('mail_'+o.id)||{}).checked);
  const delivery_id=isMail?defaultMailDeliveryId():defaultCourierDeliveryId();
  const comment=(($('cmt_'+o.id)||{}).value||'').trim();
  const parsed=parsePartnerComment(comment);
  return {
    delivery_id:delivery_id,
    track:(($('trk_'+o.id)||{}).value||'').trim(),
    comment:comment,
    client:parsed.client||o.client||'',
    phone:parsed.phone||o.phone||'',
    address:parsed.address||o.address||'',
  };
}

// экран заполнения сразу нескольких новых заказов
function partnerFillOrders(partner,orders){
  document.body.innerHTML=`
  <div class="pcab">
    <div class="pcab-top"><div class="pcab-brand">
      <img class="pcab-logo-img" src="data:image/png;base64," alt="Jyldam Logistics">
      <div><div class="pcab-store">${esc(partner.name)}</div><div class="pcab-sub">Заполните ${orders.length} заказ(ов)</div></div>
    </div></div>
    <div id="pfill" class="pcab-list"></div>
    <button class="pcab-call" id="pfillDone">Готово</button>
    <button class="pcab-call pcab-ghost" id="pfillBack">← В кабинет</button>
  </div>
  <div id="scanOverlay" class="scan-ov" style="display:none">
    <div class="scan-box"><div id="scanReader"></div>
      <button class="pcab-call pcab-ghost" id="scanCancel" style="margin-top:12px">Отмена</button>
    </div>
  </div>`;
  const wrap=$('pfill');
  const renderCards=()=>{
    const warn=(S.delivery||[]).length?'':`<div class="pcab-lockmsg" style="background:#fdf3d6;border-color:#e3cf9c;color:#8a5a12">Типы доставки не загрузились. <button type="button" id="reloadDirs" style="margin-left:6px;border:none;background:var(--rust);color:#fff;border-radius:8px;padding:4px 10px;font-weight:600">Загрузить ещё раз</button></div>`;
    wrap.innerHTML=warn+orders.map((o,i)=>partnerOrderFieldsHtml(o,i)).join('');
    wrap.querySelectorAll('[data-mailchk]').forEach(c=>c.onchange=()=>partnerToggleMail(c.dataset.mailchk));
    wrap.querySelectorAll('[data-courchk]').forEach(c=>c.onchange=()=>partnerToggleCourier(c.dataset.courchk));
    wrap.querySelectorAll('[data-scan]').forEach(b=>{
      b.onclick=()=>startScan(code=>{const inp=$('trk_'+b.dataset.scan);if(inp)inp.value=code;});
    });
    wrap.querySelectorAll('[data-printlbl]').forEach(b=>{
      b.onclick=()=>printPartnerOrderLabel(orders.find(x=>x.id===b.dataset.printlbl),partner);
    });
    const rb=$('reloadDirs');
    if(rb)rb.onclick=async()=>{rb.textContent='Загрузка…';rb.disabled=true;await loadPartnerDirs();renderCards();};
  };
  renderCards();
  $('scanCancel').onclick=stopScan;
  $('pfillBack').onclick=()=>renderPartnerCabinet(partner);
  $('pfillDone').onclick=async()=>{
    const btn=$('pfillDone');btn.disabled=true;btn.textContent='Сохраняем…';
    try{
      for(const o of orders){
        const r=await callPartnerCabinet('update_order',{order_id:o.id,fields:partnerCollectFields(o)});
        if(r.error)throw new Error(r.error);
      }
      alert('Заказы сохранены! Курьер заберёт посылки.');
      renderPartnerCabinet(partner);
    }catch(e){
      btn.disabled=false;btn.textContent='Готово';
      alert('Ошибка сохранения: '+(e&&e.message||e));
    }
  };
}

// экран редактирования ОДНОГО существующего заказа (по тапу из списка)
function partnerEditOrder(partner,orderId){
  const o=(partner.__orders||[]).find(x=>x.id===orderId);
  if(!o)return;
  const collected=partnerOrderCollected(o);
  document.body.innerHTML=`
  <div class="pcab">
    <div class="pcab-top"><div class="pcab-brand">
      <img class="pcab-logo-img" src="data:image/png;base64," alt="Jyldam Logistics">
      <div><div class="pcab-store">${esc(partner.name)}</div><div class="pcab-sub">${collected?'Просмотр заказа':'Редактирование заказа'} #${esc(o.code)}</div></div>
    </div></div>
    ${collected?'<div class="pcab-lockmsg">🔒 Курьер уже забрал этот заказ — редактирование недоступно.</div>':''}
    <div id="pfill" class="pcab-list"></div>
    ${collected?'':'<button class="pcab-call" id="peditSave">Сохранить</button>'}
    <button class="pcab-call pcab-ghost" id="peditBack">← К списку</button>
  </div>
  <div id="scanOverlay" class="scan-ov" style="display:none">
    <div class="scan-box"><div id="scanReader"></div>
      <button class="pcab-call pcab-ghost" id="scanCancel" style="margin-top:12px">Отмена</button>
    </div>
  </div>`;
  $('pfill').innerHTML=partnerOrderFieldsHtml(o,null);
  // печать этикетки доступна всегда, даже после того, как курьер забрал заказ
  $('pfill').querySelectorAll('[data-printlbl]').forEach(b=>{b.onclick=()=>printPartnerOrderLabel(o,partner);});
  // если забран — блокируем все поля
  if(collected){
    $('pfill').querySelectorAll('input,select,button.pfill-scan').forEach(el=>el.disabled=true);
  }else{
    $('pfill').querySelectorAll('[data-mailchk]').forEach(c=>c.onchange=()=>partnerToggleMail(c.dataset.mailchk));
    $('pfill').querySelectorAll('[data-courchk]').forEach(c=>c.onchange=()=>partnerToggleCourier(c.dataset.courchk));
    $('pfill').querySelectorAll('[data-scan]').forEach(b=>{
      b.onclick=()=>startScan(code=>{const inp=$('trk_'+b.dataset.scan);if(inp)inp.value=code;});
    });
  }
  if($('scanCancel'))$('scanCancel').onclick=stopScan;
  $('peditBack').onclick=()=>renderPartnerCabinet(partner);
  if($('peditSave'))$('peditSave').onclick=async()=>{
    const btn=$('peditSave');btn.disabled=true;btn.textContent='Сохраняем…';
    try{
      const upd=partnerCollectFields(o);
      const r=await callPartnerCabinet('update_order',{order_id:o.id,fields:upd});
      if(r.error)throw new Error(r.error);
      if(r.order)Object.assign(o,r.order);
      alert('Заказ сохранён.');
      renderPartnerCabinet(partner);
    }catch(e){
      btn.disabled=false;btn.textContent='Сохранить';
      alert('Ошибка сохранения: '+(e&&e.message||e));
    }
  };
}


let _scanner=null;
function startScan(onResult){
  const ov=$('scanOverlay');if(!ov)return;
  ov.style.display='flex';
  if(typeof Html5Qrcode==='undefined'){alert('Сканер не загрузился, введите трек вручную');ov.style.display='none';return;}
  _scanner=new Html5Qrcode('scanReader');
  _scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:250,height:150}},
    decoded=>{onResult(decoded);stopScan();},
    ()=>{}
  ).catch(e=>{alert('Не удалось открыть камеру: '+e);ov.style.display='none';});
}
function stopScan(){
  const ov=$('scanOverlay');
  if(_scanner){_scanner.stop().then(()=>{_scanner.clear();_scanner=null;}).catch(()=>{_scanner=null;});}
  if(ov)ov.style.display='none';
}